data class UiState(val loading:Boolean=true,val authenticated:Boolean=false,val visits:List<MeasureVisit> = emptyList(),val selectedVisit:MeasureVisit?=null,val environments:List<EnvironmentEntity> = emptyList(),val selectedEnvironment:String?=null,val elements:List<ElementEntity> = emptyList(),val selectedElement:String?=null,val measurements:List<MeasurementEntity> = emptyList(),val observations:List<ObservationEntity> = emptyList(),val mutations:List<PendingMutationEntity> = emptyList(),val lastSync:String?=null,val syncOpen:Boolean=false,val error:String?=null,val configMissing:List<String> = emptyList())
class MainViewModel(private val repo:MeasureRepository):ViewModel(){private val selectedVisit=MutableStateFlow<String?>(null);private val selectedEnvironment=MutableStateFlow<String?>(null);private val selectedElement=MutableStateFlow<String?>(null);private val _state=MutableStateFlow(UiState(configMissing=repo.configuration.missing));val state=_state.asStateFlow();init{viewModelScope.launch{repo.visits().collect{v->_state.update{it.copy(visits=v,selectedVisit=v.firstOrNull{x->x.id==selectedVisit.value})}}};viewModelScope.launch{selectedVisit.flatMapLatest{if(it==null)flowOf(emptyList())else repo.environments(it)}.collect{_state.update{s->s.copy(environments=it)}}};viewModelScope.launch{selectedEnvironment.flatMapLatest{if(it==null)flowOf(emptyList())else repo.elements(it)}.collect{_state.update{s->s.copy(elements=it)}}};viewModelScope.launch{selectedElement.flatMapLatest{if(it==null)flowOf(emptyList())else repo.measurements(it)}.collect{_state.update{s->s.copy(measurements=it)}}};viewModelScope.launch{selectedVisit.flatMapLatest{if(it==null)flowOf(emptyList())else repo.observations(it)}.collect{_state.update{s->s.copy(observations=it)}}};viewModelScope.launch{repo.mutations().collect{m->_state.update{it.copy(mutations=m)}}};viewModelScope.launch{repo.lastSync().collect{x->_state.update{it.copy(lastSync=x)}}};refreshSession()}
 private fun refreshSession()=viewModelScope.launch{when(val r=repo.refresh()){is Result.Success->_state.update{it.copy(loading=false,authenticated=true,error=null)};is Result.Failure->_state.update{it.copy(loading=false,error=if(r.error is AppError.Configuration)r.error.message()else null)}}}
 fun login(email:String,password:String)=viewModelScope.launch{_state.update{it.copy(loading=true)};when(val r=repo.login(email,password)){is Result.Success->_state.update{it.copy(loading=false,authenticated=true,error=null)};is Result.Failure->_state.update{it.copy(loading=false,error=r.error.message())}}}
 fun refresh()=viewModelScope.launch{repo.refresh()};fun openVisit(v:MeasureVisit)=viewModelScope.launch{selectedVisit.value=v.id;selectedEnvironment.value=null;selectedElement.value=null;_state.update{it.copy(selectedVisit=v)};repo.loadVisit(v.id)};fun closeVisit(){selectedVisit.value=null;selectedEnvironment.value=null;selectedElement.value=null;_state.update{it.copy(selectedVisit=null)}};fun selectEnvironment(id:String){selectedEnvironment.value=id;selectedElement.value=null;_state.update{it.copy(selectedEnvironment=id,selectedElement=null)}};fun selectElement(id:String){selectedElement.value=id;_state.update{it.copy(selectedElement=id)}};fun toggleSync(){_state.update{it.copy(syncOpen=!it.syncOpen)}}
 fun saveEnvironment(name:String,existing:EnvironmentEntity?=null)=launchResult{val v=_state.value.selectedVisit?:return@launchResult Result.Failure(AppError.NotFound);val now=Instant.now().toString();repo.saveEnvironment(existing?.copy(name=name,updatedAt=now)?:EnvironmentEntity(UUID.randomUUID().toString(),repo.ownerId(),v.id,name,sequence=_state.value.environments.size,createdAt=now,updatedAt=now,syncState=SyncState.LOCAL_ONLY.name))}
 fun saveElement(name:String,type:String,existing:ElementEntity?=null)=launchResult{val v=_state.value.selectedVisit?:return@launchResult Result.Failure(AppError.NotFound);val env=selectedEnvironment.value?:return@launchResult Result.Failure(AppError.Validation(mapOf("environment" to listOf("Selecione um ambiente."))));val now=Instant.now().toString();repo.saveElement(existing?.copy(name=name,type=type,updatedAt=now)?:ElementEntity(UUID.randomUUID().toString(),repo.ownerId(),v.id,env,name,type=type,sequence=_state.value.elements.size,createdAt=now,updatedAt=now,syncState=SyncState.LOCAL_ONLY.name))}
 fun duplicateElement(id:String,copy:Boolean)=launchResult{repo.duplicateElement(id,copy).mapUnit()}
 fun saveMeasurement(name:String,value:String,type:String,unit:String,state:String="provisoria",existing:MeasurementEntity?=null)=launchResult{val v=_state.value.selectedVisit?:return@launchResult Result.Failure(AppError.NotFound);val element=selectedElement.value?:return@launchResult Result.Failure(AppError.Validation(mapOf("element" to listOf("Selecione um elemento."))));when(val parsed=parseDecimal(value,type)){is Result.Failure->parsed;is Result.Success->{val now=Instant.now().toString();repo.saveMeasurement(existing?.copy(name=name,value=parsed.value,type=type,unit=unit,state=state,updatedAt=now)?:MeasurementEntity(UUID.randomUUID().toString(),repo.ownerId(),v.id,element,type=type,name=name,value=parsed.value,unit=unit,state=state,measuredAt=now,createdAt=now,updatedAt=now,syncState=SyncState.LOCAL_ONLY.name))}}}
 fun saveObservation(text:String,category:String,important:Boolean=false,existing:ObservationEntity?=null)=launchResult{val v=_state.value.selectedVisit?:return@launchResult Result.Failure(AppError.NotFound);val now=Instant.now().toString();repo.saveObservation(existing?.copy(text=text,category=category,important=important,updatedAt=now)?:ObservationEntity(UUID.randomUUID().toString(),repo.ownerId(),v.id,environmentId=selectedEnvironment.value,elementId=selectedElement.value,category=category,text=text,important=important,createdAt=now,updatedAt=now,syncState=SyncState.LOCAL_ONLY.name))}
 fun resolveObservation(x:ObservationEntity)=launchResult{repo.saveObservation(x.copy(resolvedAt=if(x.resolvedAt==null)Instant.now().toString()else null))};fun sync()=launchResult{repo.retrySync().mapUnit()};fun transition(action:String)=launchResult{val v=_state.value.selectedVisit?:return@launchResult Result.Failure(AppError.NotFound);repo.transition(v.id,action,v.version)}
 fun archiveEnvironment(x:EnvironmentEntity)=launchResult{repo.saveEnvironment(x.copy(deletedAt=Instant.now().toString(),syncState=SyncState.DELETED_PENDING.name))};fun archiveElement(x:ElementEntity)=launchResult{repo.saveElement(x.copy(deletedAt=Instant.now().toString(),syncState=SyncState.DELETED_PENDING.name))};fun toggleAttention(x:ElementEntity)=launchResult{repo.saveElement(x.copy(attention=!x.attention))};fun moveEnvironment(x:EnvironmentEntity,delta:Int)=launchResult{repo.saveEnvironment(x.copy(sequence=(x.sequence+delta).coerceAtLeast(0)))};fun moveElement(x:ElementEntity,delta:Int)=launchResult{repo.saveElement(x.copy(sequence=(x.sequence+delta).coerceAtLeast(0)))}
 private fun launchResult(block:suspend()->Result<Unit>)=viewModelScope.launch{when(val r=block()){is Result.Success->_state.update{it.copy(error=null)};is Result.Failure->_state.update{it.copy(error=r.error.message())}}}
}
private fun<T> Result<T>.mapUnit()=when(this){is Result.Success->Result.Success(Unit);is Result.Failure->this}
private fun AppError.message()=when(this){AppError.AuthenticationRequired->"Sua sessão expirou. Entre novamente.";AppError.PermissionDenied->"Você não possui permissão para esta ação.";is AppError.Configuration->"Configuração de desenvolvimento ausente: ${missing.joinToString()}.";is AppError.VersionConflict->"A visita foi alterada em outro dispositivo.";AppError.EntityLocked->"O estado atual não permite esta alteração.";AppError.NetworkUnavailable->"Não foi possível enviar agora. O dado permanece salvo no aparelho.";is AppError.Validation->fields.values.flatten().firstOrNull()?:"Revise os campos.";is AppError.Unknown->if(BuildConfig.DEBUG)"Falha técnica: ${cause?.javaClass?.simpleName}: ${cause?.message}" else "Não foi possível concluir a operação.";else->"Não foi possível concluir a operação."}
class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);enableEdgeToEdge();val repo=(application as SquadMeasureApp).container.repository;setContent{SquadTheme{val vm:MainViewModel=viewModel(factory=object:ViewModelProvider.Factory{override fun<T:ViewModel>create(c:Class<T>):T=@Suppress("UNCHECKED_CAST")(MainViewModel(repo) as T)});App(vm)}}}}

@OptIn(ExperimentalMaterial3Api::class)@Composable fun App(vm:MainViewModel){val s by vm.state.collectAsState();Scaffold(topBar={TopAppBar(title={Text("SquadMeasure")},actions={if(s.authenticated)TextButton(onClick=vm::toggleSync){Text("Sincronização (${s.mutations.size})")}})}){p->Box(Modifier.padding(p).padding(16.dp)){when{s.loading->CircularProgressIndicator();!s.authenticated->LoginScreen(s,vm::login);s.syncOpen->SyncScreen(s,vm::toggleSync,vm::sync);s.selectedVisit!=null->FieldScreen(s,vm);else->VisitList(s.visits,vm::refresh,vm::openVisit)}}}}
@Composable fun LoginScreen(s:UiState,login:(String,String)->Unit){var email by remember{mutableStateOf("")};var pass by remember{mutableStateOf("")};Column(verticalArrangement=Arrangement.spacedBy(12.dp)){Text("Acesso de campo",style=MaterialTheme.typography.headlineMedium);if(s.configMissing.isNotEmpty())Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.errorContainer)){Text("Ambiente não configurado: ${s.configMissing.joinToString()}.",Modifier.padding(12.dp))};OutlinedTextField(email,{email=it},label={Text("E-mail")},modifier=Modifier.fillMaxWidth());OutlinedTextField(pass,{pass=it},label={Text("Senha")},visualTransformation=PasswordVisualTransformation(),modifier=Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};SquadButton("Entrar",{login(email,pass)},email.isNotBlank()&&pass.isNotBlank()&&s.configMissing.isEmpty(),Modifier.fillMaxWidth())}}
@Composable fun VisitList(visits:List<MeasureVisit>,refresh:()->Unit,open:(MeasureVisit)->Unit){Column{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Visitas",style=MaterialTheme.typography.headlineMedium);TextButton(onClick=refresh){Text("Atualizar")}};if(visits.isEmpty())Text("Nenhuma visita armazenada neste aparelho.");LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(visits){v->Card(onClick={open(v)},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text(v.workName,style=MaterialTheme.typography.titleMedium);Text(v.clientName?:"Cliente não informado");Text("${v.status.name.replace('_',' ')} · ${v.progress}%")}}}}}}
@Composable fun FieldScreen(s:UiState,vm:MainViewModel){val v=s.selectedVisit!!;var envName by remember{mutableStateOf("")};var elementName by remember{mutableStateOf("")};var measureName by remember{mutableStateOf("Largura superior")};var measureValue by remember{mutableStateOf("")};var observation by remember{mutableStateOf("")};LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){item{TextButton(onClick=vm::closeVisit){Text("← Visitas")};Text(v.workName,style=MaterialTheme.typography.headlineMedium);Text(v.clientName?:"Cliente não informado");Text(v.address?:"Endereço não informado");Text("Status: ${v.status.name} · progresso confirmado: ${v.progress}%");LinearProgressIndicator({v.progress/100f},Modifier.fillMaxWidth());Text("Última sincronização: ${s.lastSync?:"nunca"}");Text("Alterações pendentes: ${s.mutations.count{it.visitId==v.id}}")};item{Text("Ambientes",style=MaterialTheme.typography.titleLarge);OutlinedTextField(envName,{envName=it},label={Text("Nome do ambiente")},modifier=Modifier.fillMaxWidth());Button(onClick={vm.saveEnvironment(envName);envName=""},enabled=envName.isNotBlank()){Text("Adicionar ambiente")}};items(s.environments){e->SyncCard(e.name,e.syncState,e.lastErrorMessage,{vm.selectEnvironment(e.id)}){Row{TextButton(onClick={vm.saveEnvironment("${e.name} editado",e)}){Text("Editar")};TextButton(onClick={vm.moveEnvironment(e,-1)}){Text("↑")};TextButton(onClick={vm.moveEnvironment(e,1)}){Text("↓")};TextButton(onClick={vm.archiveEnvironment(e)}){Text("Arquivar")}}}};item{HorizontalDivider();Text("Elementos",style=MaterialTheme.typography.titleLarge);OutlinedTextField(elementName,{elementName=it},label={Text("Nome do elemento")},modifier=Modifier.fillMaxWidth());Button(onClick={vm.saveElement(elementName,"janela");elementName=""},enabled=s.selectedEnvironment!=null&&elementName.isNotBlank()){Text("Adicionar elemento")}};items(s.elements){e->SyncCard(e.name,e.syncState,e.lastErrorMessage,{vm.selectElement(e.id)}){Row{TextButton(onClick={vm.saveElement("${e.name} editado",e.type,e)}){Text("Editar")};TextButton(onClick={vm.duplicateElement(e.id,false)}){Text("Duplicar")};TextButton(onClick={vm.toggleAttention(e)}){Text(if(e.attention)"Atenção ✓" else "Atenção")};TextButton(onClick={vm.archiveElement(e)}){Text("Arquivar")}}}};item{HorizontalDivider();Text("Medidas",style=MaterialTheme.typography.titleLarge);OutlinedTextField(measureName,{measureName=it},label={Text("Nome")},modifier=Modifier.fillMaxWidth());OutlinedTextField(measureValue,{measureValue=it},label={Text("Valor (mm)")},modifier=Modifier.fillMaxWidth());Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={vm.saveMeasurement(measureName,measureValue,"largura","mm");measureValue=""},enabled=s.selectedElement!=null&&measureValue.isNotBlank()){Text("Salvar")};OutlinedButton(onClick={vm.saveMeasurement(measureName,measureValue,"largura","mm","revisar")},enabled=s.selectedElement!=null&&measureValue.isNotBlank()){Text("Revisar")}}};items(s.measurements){m->SyncCard("${m.name}: ${m.value} ${m.unit} · ${m.state}",m.syncState,m.lastErrorMessage,null){Row{TextButton(onClick={vm.saveMeasurement(m.name,m.value.toString(),m.type,m.unit,"confirmada",m)}){Text("Confirmar")};TextButton(onClick={vm.saveMeasurement(m.name,m.value.toString(),m.type,m.unit,"invalidada",m)}){Text("Invalidar")}}}};item{HorizontalDivider();Text("Observações",style=MaterialTheme.typography.titleLarge);OutlinedTextField(observation,{observation=it},label={Text("Observação")},modifier=Modifier.fillMaxWidth());Button(onClick={vm.saveObservation(observation,"informacao");observation=""},enabled=observation.isNotBlank()){Text("Adicionar observação")}};items(s.observations){o->SyncCard("${o.category}: ${o.text}",o.syncState,o.lastErrorMessage,null){TextButton(onClick={vm.resolveObservation(o)}){Text(if(o.resolvedAt==null)"Resolver" else "Reabrir")}}};item{s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};HorizontalDivider();Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton(onClick={vm.transition("start")}){Text("Iniciar")};OutlinedButton(onClick={vm.transition("pause")}){Text("Pausar")};OutlinedButton(onClick={vm.transition("resume")}){Text("Retomar")}};Button(onClick={vm.transition("submit_review")},enabled=s.mutations.none{it.visitId==v.id},modifier=Modifier.fillMaxWidth()){Text("Enviar para revisão")};Spacer(Modifier.height(24.dp))}}
}
@Composable fun SyncCard(title:String,state:String,error:String?,select:(() -> Unit)?,content:@Composable () -> Unit){Card(onClick=select?:{},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(title);Text(state,color=if(state==SyncState.ERROR.name||state==SyncState.CONFLICT.name)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.labelSmall);error?.let{Text(it,color=MaterialTheme.colorScheme.error)};content()}}}
@Composable fun SyncScreen(s:UiState,back:()->Unit,sync:()->Unit){Column(verticalArrangement=Arrangement.spacedBy(12.dp)){TextButton(onClick=back){Text("← Campo")};Text("Sincronização",style=MaterialTheme.typography.headlineMedium);Text("Última sincronização: ${s.lastSync?:"nunca"}");Text("Pendentes: ${s.mutations.count{it.status=="PENDING"}}");Text("Erros: ${s.mutations.count{it.status=="ERROR"}}");Text("Conflitos: ${s.mutations.count{it.status=="CONFLICT"}}");Button(onClick=sync,modifier=Modifier.fillMaxWidth()){Text("Sincronizar agora")};LazyColumn{items(s.mutations){m->ListItem(headlineContent={Text("${m.entityType}: ${m.operation}")},supportingContent={Text("${m.status} · tentativa ${m.attemptCount}${m.lastErrorCode?.let{" · $it"}?:""}")})}}}}
